# Add more triggers
TRIGGERS_LIST_V5 = TRIGGERS_LIST + [
    r"selection of",
    r"mix of",
    r"seeking",
    r"options for",
    r"encompassing",
    r"enjoying",
    r"array of",
    r"experience with options for",
    r"with options for",
]

def extract_cats_v5(desc):
    txt = desc
    m = re.search(r'\b[A-Z]{2}\b,\s*(.*)', txt)
    if m:
        txt = m.group(1)

    best = []
    for trig in TRIGGERS_LIST_V5:
        for m2 in re.finditer(trig, txt, re.IGNORECASE):
            body = txt[m2.end():]
            best_stop = len(body)
            for s in STOPS:
                m3 = re.search(s, body)
                if m3 and m3.start() < best_stop and m3.start() > 0:
                    best_stop = m3.start()
            body2 = body[:best_stop]
            parts = re.split(r",\s*(?:and\s+|to\s+)?|\s+and\s+", body2)
            parts = [p.strip(" '\".") for p in parts if p.strip()]
            cleaned = []
            for p in parts:
                if len(p) < 2 or len(p) > 50:
                    continue
                if not p[0].isupper():
                    continue
                bad = ['cuisine', 'atmosphere', 'meal', 'spot', 'place', 'destination', 'experience', 
                       'time', 'occasion', 'flavors', 'dishes', 'palate', 'gatherings', 'celebrations',
                       'tastes', 'preferences', 'craving', 'maintenance', 'travelers', 'organizers',
                       'eye care services', 'establishment', 'family', 'needs', 'products in', 'options for']
                low = p.lower()
                if any(b in low for b in bad):
                    continue
                cleaned.append(p)
            if len(cleaned) > len(best):
                best = cleaned
    return best

